-- Read-only research snapshot, 2026-11-05. No individual profile data exported.

with people as (select distinct candid_id from public.experience_user where company_id in (16783,2824374,10571084,1753)),
e as (select distinct x.candid_id,x.company_id,x.start_date,x.end_date from public.experience_user x join people p using(candid_id) where x.company_id is not null and x.start_date is not null and x.start_date < date '2026-11-06'),
ordered as (select *,lag(company_id) over(partition by candid_id order by start_date,coalesce(end_date,date '9999-12-31'),company_id) prev_company from e),
grouped as (select *,sum(case when prev_company is distinct from company_id then 1 else 0 end) over(partition by candid_id order by start_date,coalesce(end_date,date '9999-12-31'),company_id) grp from ordered),
episodes as (select candid_id,company_id,grp,min(start_date) started,case when bool_or(end_date is null) then null else max(end_date) end ended from grouped group by 1,2,3),
moves as (select *,lead(company_id) over(partition by candid_id order by grp) destination,lead(started) over(partition by candid_id order by grp) next_started from episodes),
a as (select m.company_id source,c.id destination,c.name,c.linkedin_url,count(distinct m.candid_id)::int people,percentile_cont(0.5) within group(order by (m.ended-m.started)/365.25) as median_tenure from moves m join public.company_db c on c.id=m.destination where m.company_id in (16783,2824374,10571084,1753) and m.ended is not null and m.ended <= m.next_started and m.next_started>=date '2020-01-01' and m.next_started<date '2026-11-06' group by 1,2),
ranked as (select *,row_number() over(partition by source order by people desc,destination) rk,sum(people) over(partition by source) total from a)
select * from ranked where rk<=12 order by source,rk;

with people as (select distinct candid_id from public.experience_user where company_id in (16783,2824374,10571084,1753)),
e as (select distinct x.candid_id,x.company_id,x.start_date,x.end_date from public.experience_user x join people p using(candid_id) where x.company_id is not null and x.start_date is not null and x.start_date < date '2026-11-06'),
ordered as (select *,lag(company_id) over(partition by candid_id order by start_date,coalesce(end_date,date '9999-12-31'),company_id) prev_company from e),
grouped as (select *,sum(case when prev_company is distinct from company_id then 1 else 0 end) over(partition by candid_id order by start_date,coalesce(end_date,date '9999-12-31'),company_id) grp from ordered),
episodes as (select candid_id,company_id,grp,min(start_date) started,case when bool_or(end_date is null) then null else max(end_date) end ended from grouped group by 1,2,3),
moves as (select *,lead(company_id) over(partition by candid_id order by grp) destination,lead(started) over(partition by candid_id order by grp) next_started from episodes),
a as (select m.company_id source,c.id destination,c.name,c.linkedin_url,count(distinct m.candid_id)::int people,percentile_cont(0.5) within group(order by (m.ended-m.started)/365.25) as median_tenure from moves m join public.company_db c on c.id=m.destination where m.company_id in (16783,2824374,10571084,1753) and m.ended is not null and m.ended-m.started>=365 and m.ended <= m.next_started and m.next_started>=date '2020-01-01' and m.next_started<date '2026-11-06' group by 1,2),
ranked as (select *,row_number() over(partition by source order by people desc,destination) rk,sum(people) over(partition by source) total from a)
select * from ranked where rk<=8 order by source,rk;

with topics(id,label,pattern) as (values ('backend','백엔드','(백엔드|백앤드|back.?end)'),('frontend','프론트엔드','(프론트엔드|front.?end)'),('data','데이터 엔지니어','(데이터.?엔지니어|data engineer)'),('ml','AI · 머신러닝','(머신러닝|machine learning|\mAI\M|\mML\M)'),('design','프로덕트 디자인','(프로덕트.?디자|product design)'),('pm','프로덕트 매니저','(프로덕트.?매니저|product manager)')), jobs as (select r.* from public.company_roles r where r.source_type='external' and r.country_code='KR' and r.source_provider='zighang' and r.information->>'testOnly' is distinct from 'true') select t.id,t.label, count(*) filter(where j.is_expired is not true) active,count(distinct j.company_workspace_id) filter(where j.is_expired is not true) companies,count(*) filter(where j.posted_at>='2026-10-05' and j.posted_at<'2026-10-12') w1,count(*) filter(where j.posted_at>='2026-10-12' and j.posted_at<'2026-10-19') w2,count(*) filter(where j.posted_at>='2026-10-19' and j.posted_at<'2026-10-26') w3,count(*) filter(where j.posted_at>='2026-10-26' and j.posted_at<'2026-11-02') w4,count(*) filter(where j.posted_at>='2026-09-07' and j.posted_at<'2026-10-05') prev28,count(*) filter(where j.posted_at>='2026-10-05' and j.posted_at<'2026-11-02') last28 from topics t join jobs j on j.name~*t.pattern group by t.id,t.label;

with topics(id,label,pattern) as (values ('backend','백엔드','(백엔드|백앤드|back.?end)'),('frontend','프론트엔드','(프론트엔드|front.?end)'),('data','데이터 엔지니어','(데이터.?엔지니어|data engineer)'),('ml','AI · 머신러닝','(머신러닝|machine learning|\mAI\M|\mML\M)'),('design','프로덕트 디자인','(프로덕트.?디자|product design)'),('pm','프로덕트 매니저','(프로덕트.?매니저|product manager)')), jobs as (select *, (salary_min+salary_max)/2 as midpoint from public.company_roles where source_type='external' and country_code='US' and is_expired is not true and salary_is_predicted=false and salary_currency='USD' and salary_period in ('year','yearly','annual','annually') and salary_min>0 and salary_max>=salary_min and role_id not in ('3fc1ef91-33d6-4915-bb5d-0e96f4f7d48b','33883927-48f7-4bf2-80fc-215ef4a86b46','eadf46b4-d32c-46fc-bb80-003892990e11') and information->>'testOnly' is distinct from 'true') select t.id,t.label,count(*) n,round(avg(midpoint)) mean,percentile_cont(array[0.1,0.25,0.5,0.75,0.9]) within group(order by midpoint) percentiles, min(salary_min) minimum,max(salary_max) maximum from topics t join jobs j on j.name~*t.pattern group by t.id,t.label;

select w.company_db_id,count(*) n from company_roles r join company_workspace w using(company_workspace_id) where r.is_expired is not true and r.source_type='external' and r.country_code='KR' and r.information->>'testOnly' is distinct from 'true' and w.company_db_id in (16783,2824374,1441,825160,2382910,77752302,3996614,162479,26665462,9318303,42772889,10571084,13340368,13389963,6476200,14593491,27052530,2741466,69347140,10043024,69924947,67515813,74324665,82568965,80128583,65282143,13714067,1753) group by 1;
